shellCommands.command:
(npm run start > /tmp/next2.log 2>&1 &) ; sleep 6
echo "--- /blog/9999 (missing post) ---"; curl -s -o /tmp/p.html -w 'status=%{http_code}
' localhost:3000/blog/9999; grep -oc '404 - Page Not Found' /tmp/p.html
echo "--- /blog/42 (valid, on-demand) ---"; curl -s -o /dev/null -w 'status=%{http_code}
' localhost:3000/blog/42
echo "--- API GET /api/posts ---"; curl -s -w '
status=%{http_code}
' localhost:3000/api/posts
echo "--- API POST valid ---"; curl -s -w '
status=%{http_code}
' -X POST localhost:3000/api/posts -H 'content-type: application/json' -d '{"title":"t","content":"c"}'
echo "--- API POST missing fields ---"; curl -s -w '
status=%{http_code}
' -X POST localhost:3000/api/posts -H 'content-type: application/json' -d '{"title":"t"}'
echo "--- API POST bad json ---"; curl -s -w '
status=%{http_code}
' -X POST localhost:3000/api/posts -H 'content-type: application/json' -d 'not-json'
echo "--- API 405 on unsupported (DELETE /api/posts) ---"; curl -s -o /dev/null -D /tmp/h.txt -w 'status=%{http_code}
' -X DELETE localhost:3000/api/posts; grep -i '^allow' /tmp/h.txt

node -e '
const {execSync}=require("child_process");
const out=execSync("ss -ltnp 2>/dev/null || true").toString();
const line=out.split("\n").find(l=>l.includes(":3000"));
console.log("listener:", line||"none");
const m=line&&line.match(/pid=(\d+)/);
if(m){process.kill(+m[1]);console.log("killed",m[1]);}
'

node -e '
const fs=require("fs");
for(const p of fs.readdirSync("/proc").filter(d=>/^\d+$/.test(d))){
  try{
    const c=fs.readFileSync(`/proc/${p}/cmdline`,"utf8");
    if(c.includes("next-server")||c.includes("next/dist/bin/next")){ process.kill(+p); console.log("killed",p); }
  }catch{}
}' ; sleep 1; curl -s -m 2 -o /dev/null -w 'port 3000: %{http_code}\n' localhost:3000 || echo "port 3000: closed"
rm -rf /workspace/.next /workspace/tsconfig.tsbuildinfo
git status --short
